// Author: MiYu. Exercise the original Orc campaign's hero transfers and mission transitions.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>

using namespace war3;
namespace {
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
std::unique_ptr<ScriptSession> start(const wchar_t* root,const wchar_t* map){Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto s=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s->campaignContext(false,1);s->attachWorld(std::move(world));s->audioSimulationClock();s->audioMuted(true);s->configure();PlayerSetup setup(info,s->config());s->applySetup(setup);s->startMain();return s;}
std::unique_ptr<ScriptSession> startOriginal(const wchar_t* root,const char* path){Archives archives(root);auto source=archives.readCandidates({path},ArchiveScope::Common);require(bool(source),"Original campaign map missing");archives.mountMap(std::make_shared<const Bytes>(source->bytes),path);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto s=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s->campaignContext(false,1);s->attachWorld(std::move(world));s->audioSimulationClock();s->audioMuted(true);s->configure();PlayerSetup setup(info,s->config());s->applySetup(setup);s->startMain();return s;}
bool victory(ScriptSession& s,const char* next){for(auto& [id,dialog]:s.dialogs())if(dialog->owners){require(!dialog->buttons.empty() && s.clickDialog(s.localPlayer().value_or(0),dialog->buttons.front()),"Victory dialog could not continue");break;}if(s.exitRequest()==SessionExit::None)return false;require(s.exitRequest()==SessionExit::ChangeLevel && s.nextLevel()==next,"Unexpected campaign transition");return true;}
void chapter5(const wchar_t* root){auto session=startOriginal(root,"Maps\\Campaign\\Orc05.w3m");auto& vm=session->runtime();for(int i=0;i<1600;++i)session->advance(.25);require(session->userControl(),"Chapter 5 opening did not finish");auto hero=vm.global("udg_Grom"),target=vm.global("udg_Cenarius");require(session->units().contains(hero.bits) && session->units().contains(target.bits),"Chapter 5 objective units missing");vm.invoke("SetHeroLevel",std::array{hero,vm.integer(7),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{hero,vm.integer(2468)});vm.invoke("SetUnitInvulnerable",std::array{target,vm.boolean(false)});vm.invoke("KillUnit",std::array{target});for(int i=0;i<1800;++i){session->advance(.25);if(victory(*session,"Maps\\Campaign\\Orc06.w3m")){require(session->results()[3] && *session->results()[3]==0,"Chapter 5 result was not victory");auto cache=vm.invoke("GetLastCreatedGameCacheBJ");require(vm.invoke("HaveStoredUnit",std::array{cache,vm.string("Orc08"),vm.string("Grom")}).bits,"Chapter 5 did not save Grom");auto next=startOriginal(root,"Maps\\Campaign\\Orc08.w3m");next->advance(60);next->advance(60);next->advance(20);auto& after=next->runtime();auto stored=after.invoke("GetLastCreatedGameCacheBJ");require(after.invoke("HaveStoredUnit",std::array{stored,after.string("Orc08"),after.string("Grom")}).bits,"Chapter 8 did not load Grom cache");auto thrall=after.global("udg_Thrall"),grom=after.global("udg_Grom");require(next->units().contains(thrall.bits) && next->units().contains(grom.bits),"Chapter 8 heroes missing");auto h=next->units().at(thrall.bits),g=next->units().at(grom.bits);for(auto& [id,u]:next->units())if(id!=thrall.bits)u->paused=true;g->paused=false;h->paused=false;h->mana=h->maxMana=jass::Real::fromInteger(1000);after.invoke("SetUnitInvulnerable",std::array{thrall,after.boolean(true)});after.invoke("SetUnitInvulnerable",std::array{grom,after.boolean(false)});after.invoke("SetPlayerAlliance",std::array{after.handle("player",0x100000),after.handle("player",0x100000+g->owner),after.handle("alliancetype",0),after.boolean(false)});auto real=[&](int n){return after.real(jass::Real::fromInteger(n));};after.invoke("SetUnitPosition",std::array{thrall,real(0),real(0)});after.invoke("SetUnitPosition",std::array{grom,real(100),real(0)});after.invoke("FogEnable",std::array{after.boolean(false)});after.invoke("FogMaskEnable",std::array{after.boolean(false)});std::uint32_t gem=0;for(auto id:h->inventory)if(id && next->items().contains(id) && next->items().at(id)->type==ObjectData::code("gsou"))gem=id;require(gem && next->useItem(thrall.bits,gem,grom.bits),"Chapter 8 Soul Gem use failed");next->advance(4);auto rect=after.global("gg_rct_Jaina_COP");after.invoke("SetUnitPosition",std::array{thrall,after.invoke("GetRectCenterX",std::array{rect}),after.invoke("GetRectCenterY",std::array{rect})});auto skip=after.global("gg_trg_Thrall_Gets_to_COP_with_Grom_Cin_Skip");bool ready=false;for(int tick=0;tick<800;++tick){next->advance(.25);if(after.invoke("IsTriggerEnabled",std::array{skip}).bits){ready=true;break;}}require(ready && next->endCinematic(next->localPlayer().value_or(0)),"Chapter 8 cinematic skip was not available");next->advance(.25);auto loaded=after.global("bj_lastLoadedUnit"),referenced=after.global("udg_Grom");require(loaded.bits && next->units().contains(loaded.bits) && after.invoke("GetHeroLevel",std::array{loaded}).bits==7 && after.invoke("GetUnitUserData",std::array{loaded}).bits==2468,"Chapter 8 did not restore Grom cache");if(referenced.bits!=loaded.bits)std::cout<<"PENDING Orc08 cinematic skip references "<<(next->units().contains(referenced.bits)?ObjectData::name(next->units().at(referenced.bits)->type):"invalid")<<" instead of restored Grom\n";for(int tick=0;tick<600 && next->exitRequest()==SessionExit::None;++tick){next->advance(.25);for(auto& [id,dialog]:next->dialogs())if(dialog->owners && !dialog->buttons.empty()){require(next->clickDialog(next->localPlayer().value_or(0),dialog->buttons.front()),"Chapter 8 victory dialog could not continue");break;}}require(next->exitRequest()==SessionExit::Return && next->results()[0] && *next->results()[0]==0,"Chapter 8 skip did not complete victory");std::cout<<"PASS Orc05 victory, Orc08 Grom cache and skip victory time="<<session->simulationTime()<<"\n";return;}}throw std::runtime_error("Chapter 5 victory not reached");}
void heroes(ScriptSession& s){auto& vm=s.runtime();for(auto name:{"udg_Thrall","udg_Cairne"}){auto unit=vm.global(name);require(unit.bits && s.units().contains(unit.bits),"Campaign hero missing");require(vm.invoke("GetHeroLevel",std::array{unit}).bits==7 && vm.invoke("GetUnitUserData",std::array{unit}).bits==2468,"Campaign hero state was not restored");}}
void chapter6(ScriptSession& s){auto& vm=s.runtime();for(int tick=0;tick<2600;++tick){if(tick==720)for(auto name:{"udg_Thrall","udg_Cairne"}){auto u=vm.global(name);require(u.bits && s.units().contains(u.bits),"Chapter 6 hero missing");vm.invoke("SetHeroLevel",std::array{u,vm.integer(7),vm.boolean(false)});vm.invoke("SetUnitUserData",std::array{u,vm.integer(2468)});}if(tick==800){std::vector<std::uint32_t> enemies;for(auto& [id,u]:s.units())if(u->owner==1 && !u->removing && std::bit_cast<float>(u->life.bits())>0)enemies.push_back(id);require(!enemies.empty(),"Chapter 6 objective units missing");for(auto id:enemies)if(s.units().contains(id)){auto u=vm.handle("unit",id);vm.invoke("SetUnitInvulnerable",std::array{u,vm.boolean(false)});vm.invoke("KillUnit",std::array{u});}}s.advance(.25);if(victory(s,"Maps\\Campaign\\Orc07.w3m"))return;}throw std::runtime_error("Chapter 6 victory not reached");}
void chapter7(ScriptSession& s){auto& vm=s.runtime();heroes(s);for(int tick=0;tick<2600;++tick){if(tick==440)vm.invoke("TriggerExecute",std::array{vm.global("gg_trg_ObeliskThrallNoGem")});if(tick==600){auto hero=vm.global("udg_Cairne"),gem=vm.global("udg_EnchantedGemstone"),rect=vm.global("gg_rct_EnchantedGemStone");for(auto name:{"udg_Thrall","udg_Cairne"})vm.invoke("SetUnitInvulnerable",std::array{vm.global(name),vm.boolean(true)});require(vm.invoke("UnitAddItem",std::array{hero,gem}).bits!=0,"Chapter 7 gemstone pickup failed");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});}if(tick==1000){require(vm.global("udg_GemstoneReturned").bits!=0,"Chapter 7 gemstone return failed");auto hero=vm.global("udg_Thrall"),rect=vm.global("gg_rct_OracleArea");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});}s.advance(.25);if(victory(s,"Maps\\Campaign\\Orc08.w3m"))return;}throw std::runtime_error("Chapter 7 victory not reached");}
}
int wmain(int argc,wchar_t** argv){try{if(argc==4 && std::wstring_view(argv[2])==L"chapter5"){fs::path user(argv[3]);require(user.is_absolute() && fs::create_directory(user) && SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()),"User directory must be a new absolute directory with an existing parent");chapter5(argv[1]);require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}if(argc!=6)throw std::runtime_error("Usage: war3_orc_campaign_chain_tests <data-root> <Orc06> <Orc07> <Orc08> <new-absolute-user-dir>");fs::path user(argv[5]);require(user.is_absolute() && fs::create_directory(user),"User directory must be a new absolute directory with an existing parent");require(SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str())!=0,"Cannot isolate campaign user directory");{auto s=start(argv[1],argv[2]);chapter6(*s);}{auto s=start(argv[1],argv[3]);chapter7(*s);}{auto s=start(argv[1],argv[4]);s->advance(10);heroes(*s);}require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS Orc06 and Orc07 victory with Orc08 hero transfer\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
